begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into public.tenants(id,name,slug)values('10000000-0000-4000-8000-000000226121','Source worker A','source-worker-a');
create function pg_temp.source_config()returns jsonb language sql immutable as $function$select $configuration${"schemaVersion":1,"kind":"dynamic","rendererVersion":"sync-v1","sourceRevision":"8b1fdf1f8637dda23d48ecdaf08e0e5978e2707a","slideType":"sport_program","seed":{"schemaVersion":1,"rendererVersion":"sync-v1","sourceRevision":"8b1fdf1f8637dda23d48ecdaf08e0e5978e2707a","family":"fixtures","orientation":"landscape","theme":"fieldflow","name":"Gekoppeld bronontwerp","club":{"name":"Source A","tagline":""},"title":"DIT IS ONZE TROTS","headline":"","body":"","subtitle":"","topLabel":"CLUB TV","footer":"","footerRight":"","rows":[],"rowsPerPage":4,"ownRowIndexes":[],"category":"","subline":"","lineup":[],"news":[],"imageCaption":"","state":"ready","style":{"motion":"geen","background":"stadium","backgroundPosition":"center","font":"Inter, sans-serif","fontChanged":false,"accent":"#1763ed","alignment":"left","scale":100,"safeMargin":5,"showLogo":true,"showFooter":true}},"secondsPerPage":3}$configuration$::jsonb$function$;

create temporary table source_worker_ids(name text primary key,id uuid not null);
grant select on source_worker_ids to service_role;
insert into public.dynamic_data_sources(id,tenant_id,name,kind)values('20000000-0000-4000-8000-000000226121','10000000-0000-4000-8000-000000226121','Actual canonical source','manual_products');
insert into source_worker_ids select 'template',version.id from public.dynamic_template_versions version join public.dynamic_templates template on template.id=version.template_id where template.slug='editorial-arena-programma-dark-landscape' and version.status='published';
create function pg_temp.queue_fixture(p_name text,p_source boolean,p_hash text,p_created timestamptz)returns uuid language plpgsql as $fn$
declare slide_id uuid:=gen_random_uuid();snapshot_id uuid:=gen_random_uuid();begin
 insert into public.dynamic_slides(id,tenant_id,name,slide_type,orientation,template_id,template_version_id,data_source_id,configuration_json)
 select slide_id,'10000000-0000-4000-8000-000000226121',p_name,'sport_program','landscape',version.template_id,version.id,'20000000-0000-4000-8000-000000226121',case when p_source then jsonb_build_object('syncConfiguration',pg_temp.source_config())else '{}'::jsonb end from public.dynamic_template_versions version where version.id=(select id from source_worker_ids where name='template');
 insert into public.dynamic_slide_snapshots(id,tenant_id,dynamic_slide_id,template_version_id,data_source_id,source_revision_hash,snapshot_data_json)
 values(snapshot_id,'10000000-0000-4000-8000-000000226121',slide_id,(select id from source_worker_ids where name='template'),'20000000-0000-4000-8000-000000226121',p_hash,jsonb_build_object('type','sport_program','sport',jsonb_build_object('items','[]'::jsonb))||case when p_source then jsonb_build_object('syncConfiguration',pg_temp.source_config())else '{}'::jsonb end);
 insert into public.dynamic_render_jobs(tenant_id,snapshot_id,created_at)values('10000000-0000-4000-8000-000000226121',snapshot_id,p_created);return snapshot_id;end;$fn$;

insert into source_worker_ids values('source',pg_temp.queue_fixture('Complete Source design',true,repeat('c',64),now()-interval '2 hours'));
set local role service_role;
create temporary table source_claim as select *from public.claim_dynamic_render_job_v2('complete-worker',30,3);
create function pg_temp.artifact(p_mime text default 'video/mp4')returns jsonb language sql stable as $fn$
select jsonb_build_object('mimeType',p_mime,'durationMs',6000,'width',1920,'height',1080,'byteLength',4096,'checksumSha256',repeat('d',64),'storagePath','tenants/'||tenant_id::text||'/assets/'||output_media_asset_id::text||'/sync-dynamic/'||repeat('d',64)||case when p_mime='video/mp4'then'.mp4'else'.png'end,
'presentation',jsonb_set(pg_temp.source_config()->'seed','{rows}','[["A","B","14:00","1"],["C","D","14:00","2"],["E","F","14:00","3"],["G","H","14:00","4"],["I","J","14:00","5"]]'),
'poster',jsonb_build_object('byteLength',1024,'checksumSha256',repeat('e',64),'storagePath','tenants/'||tenant_id::text||'/assets/'||output_media_asset_id::text||'/sync-dynamic/'||repeat('e',64)||'.png'))from source_claim;$fn$;
select throws_ok($$select public.complete_dynamic_render_job_v2((select job_id from source_claim),'complete-worker',gen_random_uuid(),pg_temp.artifact())$$,'55000','dynamic render lease lost','completion requires the exact current attempt token');
select throws_ok($$select public.complete_dynamic_render_job_v2((select job_id from source_claim),'complete-worker',(select lease_token from source_claim),pg_temp.artifact('image/png'))$$,'23514','incomplete or inconsistent Source artifact','two-page output cannot become a first-page-only PNG');
select throws_ok($$select public.complete_dynamic_render_job_v2((select job_id from source_claim),'complete-worker',(select lease_token from source_claim),jsonb_set(pg_temp.artifact(),'{durationMs}','3000'))$$,'23514','incomplete or inconsistent Source artifact','completion rejects a video missing a full page duration');
select throws_ok($$select public.complete_dynamic_render_job_v2((select job_id from source_claim),'complete-worker',(select lease_token from source_claim),jsonb_set(pg_temp.artifact(),'{storagePath}','"tenants/another/asset.mp4"'))$$,'23514','incomplete or inconsistent Source artifact','a foreign or mutable shared path cannot be published');
select throws_ok($$select public.complete_dynamic_render_job_v2((select job_id from source_claim),'complete-worker',(select lease_token from source_claim),jsonb_set(pg_temp.artifact(),'{presentation,theme}','"onzetrots-tv"'))$$,'23514','Source render presentation invalid','the rendered variant cannot change its frozen authored theme');
select throws_ok($$select public.fail_dynamic_render_job_v1((select job_id from source_claim),'complete-worker','controlled_failure','Controlled test',false)$$,'55000','dynamic render lease lost','a legacy worker with the same ID cannot fail a modern render');
select is((select status from public.dynamic_slide_snapshots where id=(select snapshot_id from source_claim)),'rendering','all rejected partial artifacts leave the snapshot incomplete');
reset role;
insert into public.media_assets(id,tenant_id,kind,title,original_file_name,mime_type,status,storage_path,file_size_bytes,checksum_sha256,width,height)values('80000000-0000-4000-8000-000000226131','10000000-0000-4000-8000-000000226121','image','Own actual logo','own.png','image/png','ready','tenants/10000000-0000-4000-8000-000000226121/assets/80000000-0000-4000-8000-000000226131/original/own.png',100,repeat('a',64),320,180);
insert into public.media_variants(tenant_id,asset_id,variant_type,storage_path,mime_type,file_size_bytes,checksum_sha256,width,height)values('10000000-0000-4000-8000-000000226121','80000000-0000-4000-8000-000000226131','original','tenants/10000000-0000-4000-8000-000000226121/assets/80000000-0000-4000-8000-000000226131/original/own.png','image/png',100,repeat('a',64),320,180);
select throws_ok($$select private.assert_sync_dynamic_render_presentation_v1((select snapshot from public.dynamic_slide_snapshots snapshot where id=(select snapshot_id from source_claim)),jsonb_set(pg_temp.artifact()->'presentation','{club,logo}',jsonb_build_object('kind','tenant','mediaAssetId','80000000-0000-4000-8000-000000226131','checksumSha256',repeat('a',64))))$$,'23514','Source render image authority invalid','an existing but unreferenced image cannot enter the trusted projection');
update public.dynamic_slide_snapshots set snapshot_data_json=jsonb_set(snapshot_data_json,'{brand}',jsonb_build_object('logoMediaAssetId','80000000-0000-4000-8000-000000226131'))where id=(select snapshot_id from source_claim);
select lives_ok($$select private.assert_sync_dynamic_render_presentation_v1((select snapshot from public.dynamic_slide_snapshots snapshot where id=(select snapshot_id from source_claim)),jsonb_set(pg_temp.artifact()->'presentation','{club,logo}',jsonb_build_object('kind','tenant','mediaAssetId','80000000-0000-4000-8000-000000226131','checksumSha256',repeat('a',64))))$$,'a typed canonical image resolves only with its checked tenant checksum');
select throws_ok($$select private.assert_sync_dynamic_render_presentation_v1((select snapshot from public.dynamic_slide_snapshots snapshot where id=(select snapshot_id from source_claim)),jsonb_set(pg_temp.artifact()->'presentation','{club,logo}',jsonb_build_object('kind','tenant','mediaAssetId','80000000-0000-4000-8000-000000226131','checksumSha256',repeat('b',64))))$$,'23514','Source render image authority invalid','a canonical image with another checksum is rejected');
set local role service_role;
select is(public.complete_dynamic_render_job_v2((select job_id from source_claim),'complete-worker',(select lease_token from source_claim),pg_temp.artifact()),(select output_media_asset_id from source_claim),'a complete two-page video finalizes through the fenced service command');
select is((select status from public.dynamic_slide_snapshots where id=(select snapshot_id from source_claim)),'ready','only the full artifact makes the snapshot ready');
select is((select sync_render_result_json->>'durationMs'from public.dynamic_slide_snapshots where id=(select snapshot_id from source_claim)),'6000','the complete playback duration is frozen with the snapshot');
select is((select kind::text||':'||mime_type||':'||duration_seconds::text from public.media_assets where id=(select output_media_asset_id from source_claim)),'video:video/mp4:6.000','the ready Media asset is an actual full video rather than an image relabel');
select is((select count(*)from public.media_variants where asset_id=(select output_media_asset_id from source_claim)),3::bigint,'original, playable H264 video and PNG poster are registered together');
select ok((select checksum_sha256=repeat('e',64)and mime_type='image/png'from public.media_variants where asset_id=(select output_media_asset_id from source_claim)and variant_type='thumbnail'),'the checked poster has an independent checksum');
select is(public.renew_dynamic_render_lease_v2((select job_id from source_claim),'complete-worker',(select lease_token from source_claim)),false,'a completed render no longer accepts lease renewals');
reset role;
select throws_ok($$update public.dynamic_slide_snapshots set sync_render_result_json='{}' where id=(select snapshot_id from source_claim)$$,'55000',null,'the complete render result becomes immutable with the ready snapshot');
select is(has_function_privilege('authenticated','public.complete_dynamic_render_job_v2(uuid,text,uuid,jsonb)','EXECUTE'),false,'Control cannot supply trusted render output');
select is(has_function_privilege('anon','private.assert_sync_dynamic_render_presentation_v1(public.dynamic_slide_snapshots,jsonb)','EXECUTE'),false,'the canonical image authority remains private');
select *from finish();rollback;
